CREATE TABLE IF NOT EXISTS exit_transition (
 exit_id TEXT NOT NULL REFERENCES exit_process(exit_id), stage TEXT NOT NULL,
 actor_id TEXT NOT NULL, occurred_at TEXT NOT NULL, PRIMARY KEY(exit_id, stage));

CREATE TABLE IF NOT EXISTS exit_archive (
 exit_id TEXT NOT NULL PRIMARY KEY REFERENCES exit_process(exit_id),
 document_json TEXT NOT NULL, sha256 TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS exit_export_grant (
 person_id TEXT NOT NULL, core_id TEXT NOT NULL, kind TEXT NOT NULL, artifact_id TEXT NOT NULL,
 artifact_json TEXT NOT NULL, PRIMARY KEY(person_id, core_id, kind, artifact_id));

CREATE TABLE IF NOT EXISTS relation_terms (
 relation_id TEXT NOT NULL PRIMARY KEY REFERENCES core_exit_relation(relation_id),
 terms_json TEXT NOT NULL, exit_policy TEXT NOT NULL);

CREATE TABLE person (
    person_id   TEXT NOT NULL PRIMARY KEY,
    created_at  TEXT NOT NULL
);

CREATE TABLE core (
    core_id     TEXT NOT NULL PRIMARY KEY,
    name        TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    state       TEXT NOT NULL
);

CREATE TABLE sync_journal (
    position INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    event_id TEXT NOT NULL UNIQUE REFERENCES event(event_id),
    record_json TEXT NOT NULL
);

CREATE TABLE sync_checkpoint (
    peer_id TEXT NOT NULL PRIMARY KEY,
    sent INTEGER NOT NULL,
    received INTEGER NOT NULL
);

CREATE TRIGGER IF NOT EXISTS provisioning_audit_no_update
BEFORE UPDATE ON provisioning_audit
BEGIN SELECT RAISE(ABORT, 'provisioning audit is append-only'); END;

CREATE TRIGGER IF NOT EXISTS provisioning_audit_no_delete
BEFORE DELETE ON provisioning_audit
BEGIN SELECT RAISE(ABORT, 'provisioning audit is append-only'); END;
